import {crownEnabled,crownSelection,validateCrownManifest} from './crown-mods.js';
// Verified native JSON installation; never read or write save-game files.
const sha=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
async function directory(root,path,create=true){for(const part of path.split('/').filter(Boolean))root=await root.getDirectoryHandle(part,{create});return root;}
async function read(root,path){const pieces=path.split('/'),name=pieces.pop(),dir=await directory(root,pieces.join('/'),false);return (await dir.getFileHandle(name)).getFile();}
async function readJSON(root,path,fallback){try{return JSON.parse(await(await read(root,path)).text());}catch(e){if(e.name==='NotFoundError')return fallback;throw new Error('A local mod setting is damaged. Export saves before resetting browser storage.');}}
async function write(root,path,bytes){const pieces=path.split('/'),name=pieces.pop(),file=await(await directory(root,pieces.join('/'))).getFileHandle(name,{create:true});const handle=await file.createSyncAccessHandle();try{handle.truncate(0);let pos=0;while(pos<bytes.length){const n=handle.write(bytes.subarray(pos),{at:pos});if(n<=0)throw new Error('Browser storage is full.');pos+=n;}handle.flush();}finally{handle.close();}}
const writeJSON=(root,path,data)=>write(root,path,new TextEncoder().encode(JSON.stringify(data)));
async function settings(root,enabled){await writeJSON(root,'user/config/modSettings.json',crownSelection(await readJSON(root,'user/config/modSettings.json',{}),enabled));}
async function fetchBytes(path,expected){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(path,{credentials:'same-origin',cache:'no-cache',signal:controller.signal});if(!r.ok)throw new Error('Crown Authority download failed ('+r.status+'). Retry before launching.');const reader=r.body.getReader(),parts=[];let size=0;try{for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>expected){await reader.cancel();throw new Error('Crown Authority download exceeded its expected size.');}parts.push(value);}}finally{reader.releaseLock();}if(size!==expected&&path!=='crown-pack/manifest.json')throw new Error('An incomplete Crown Authority file was downloaded.');const all=new Uint8Array(size);let offset=0;for(const p of parts){all.set(p,offset);offset+=p.length;}return all;}finally{clearTimeout(timer);}}
async function install(root){
 const m=validateCrownManifest(JSON.parse(new TextDecoder().decode(await fetchBytes('crown-pack/manifest.json',128*1024))));
 // Fetch and authenticate the complete small pack before changing the active preset or files.
 const files=[];for(let i=0;i<m.files.length;i++){const f=m.files[i],bytes=await fetchBytes('crown-pack/'+f.path,f.size);if(await sha(bytes)!==f.sha256)throw new Error('A Crown Authority file failed its checksum.');JSON.parse(new TextDecoder().decode(bytes));files.push({path:'h3/'+f.path,bytes});postMessage({type:'progress',message:`Preparing Crown Authority · ${i+1}/${m.files.length}`});}
 await settings(root,false);for(const f of files)await write(root,f.path,f.bytes);
 const h3=await directory(root,'h3'),wanted=new Set(m.files.map(f=>f.path));async function trim(dir,prefix){for await(const[name,handle]of dir.entries()){const p=prefix+name;if(handle.kind==='directory')await trim(handle,p+'/');else if(!wanted.has(p))await dir.removeEntry(name);}}
 await trim(await directory(h3,'Mods/crown-authority'),'Mods/crown-authority/');await settings(root,true);return {version:m.version};
}
onmessage=async({data})=>{try{const root=await navigator.storage.getDirectory();let result={};if(data.type==='status')result={enabled:crownEnabled(await readJSON(root,'user/config/modSettings.json',{}))};else if(data.type==='prepare'){if(data.enabled)result=await install(root);else await settings(root,false);}else throw new Error('Unknown Crown Authority operation.');postMessage({type:'done',...result});}catch(e){postMessage({type:'error',message:e.message||String(e)});}};
